import{_ as r,o as a,c as o,ag as e}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"Согласие на получение рекламных и информационных рассылок","description":"","frontmatter":{},"headers":[],"relativePath":"consent-marketing.md","filePath":"consent-marketing.md","lastUpdated":null}'),s={name:"consent-marketing.md"};function n(l,t,i,p,d,h){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="согласие-на-получение-рекламных-и-информационных-рассылок" tabindex="-1">Согласие на получение рекламных и информационных рассылок <a class="header-anchor" href="#согласие-на-получение-рекламных-и-информационных-рассылок" aria-label="Permalink to &quot;Согласие на получение рекламных и информационных рассылок&quot;">​</a></h1><p><strong>Оператор:</strong> ИП Ульянов Алексей Владимирович<br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><div class="info custom-block"><p class="custom-block-title">Как принимается согласие</p><p>Настоящее согласие принимается путём совершения Пользователем акцептирующего действия: отметки чекбокса «Хочу получать новости и специальные предложения GoSMS» при регистрации или в настройках профиля. Данный чекбокс <strong>не является обязательным</strong> для использования сервиса и по умолчанию не отмечен.</p></div><p>Настоящий документ оформляет согласие на получение рекламных и информационных сообщений в соответствии с Федеральным законом от 13.03.2006 № 38-ФЗ «О рекламе» (ст. 18) и Федеральным законом от 27.07.2006 № 152-ФЗ «О персональных данных».</p><p>Пользователь, предоставивший согласие, далее именуется <strong>«Субъект»</strong>.</p><h2 id="_1-что-включает-согласие" tabindex="-1">1. Что включает согласие <a class="header-anchor" href="#_1-что-включает-согласие" aria-label="Permalink to &quot;1. Что включает согласие&quot;">​</a></h2><p>Субъект даёт <strong>ИП Ульянову Алексею Владимировичу</strong> (ОГРНИП 321132600016985, далее — <strong>Оператор</strong>) согласие на:</p><p><strong>1.1.</strong> Получение рекламных и информационных сообщений о сервисе GoSMS и связанных с ним продуктах и услугах, в том числе:</p><ul><li>новостей и анонсов обновлений функциональности;</li><li>специальных предложений, акций и скидок;</li><li>информации о новых тарифных планах;</li><li>рекомендаций по использованию сервиса;</li><li>приглашений к участию в тестировании новых функций (бета-тест).</li></ul><p><strong>1.2.</strong> Обработку персональных данных Субъекта (адрес электронной почты, имя, данные активности в сервисе) в целях персонализации рассылок и анализа их эффективности.</p><h2 id="_2-каналы-распространения" tabindex="-1">2. Каналы распространения <a class="header-anchor" href="#_2-каналы-распространения" aria-label="Permalink to &quot;2. Каналы распространения&quot;">​</a></h2><p>Сообщения могут направляться по следующим каналам:</p><table tabindex="0"><thead><tr><th>Канал</th><th>Адрес/идентификатор</th></tr></thead><tbody><tr><td>Электронная почта (email)</td><td>Адрес, указанный при регистрации</td></tr><tr><td>Push-уведомления</td><td>В приложении GoSMS Client</td></tr><tr><td>Уведомления в личном кабинете</td><td>Веб-кабинет gosms.ru</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>SMS-рассылки маркетингового характера <strong>не осуществляются</strong> без отдельного согласия.</p></div><h2 id="_3-периодичность-и-характер-рассылок" tabindex="-1">3. Периодичность и характер рассылок <a class="header-anchor" href="#_3-периодичность-и-характер-рассылок" aria-label="Permalink to &quot;3. Периодичность и характер рассылок&quot;">​</a></h2><p>3.1. Сообщения направляются по мере появления значимых новостей и предложений, но <strong>не чаще одного раза в неделю</strong> для массовых рассылок.</p><p>3.2. Транзакционные уведомления (подтверждение оплаты, уведомления системы безопасности, техническая информация) направляются вне зависимости от настоящего согласия и относятся к исполнению договора.</p><h2 id="_4-срок-деиствия-согласия" tabindex="-1">4. Срок действия согласия <a class="header-anchor" href="#_4-срок-деиствия-согласия" aria-label="Permalink to &quot;4. Срок действия согласия&quot;">​</a></h2><p>Согласие действует с момента его предоставления <strong>бессрочно</strong> — до отзыва.</p><h2 id="_5-право-на-отказ-отзыв-согласия" tabindex="-1">5. Право на отказ (отзыв согласия) <a class="header-anchor" href="#_5-право-на-отказ-отзыв-согласия" aria-label="Permalink to &quot;5. Право на отказ (отзыв согласия)&quot;">​</a></h2><p>5.1. Субъект вправе <strong>в любое время</strong> отказаться от получения рекламных и информационных рассылок любым из следующих способов:</p><ul><li>нажать кнопку «Отписаться» / «Unsubscribe» в нижней части любого полученного письма;</li><li>отключить уведомления в настройках профиля в личном кабинете (раздел «Уведомления»);</li><li>направить запрос на отписку на адрес <strong><a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></strong> с темой «Отписаться от рассылки».</li></ul><p>5.2. Оператор прекращает направлять рекламные сообщения в течение <strong>3 (трёх) рабочих дней</strong> с момента получения отказа.</p><p>5.3. Отказ от рекламных рассылок <strong>не влияет</strong> на возможность использования Сервиса и не является отзывом согласия на обработку персональных данных в целях исполнения договора.</p><h2 id="_6-защита-данных" tabindex="-1">6. Защита данных <a class="header-anchor" href="#_6-защита-данных" aria-label="Permalink to &quot;6. Защита данных&quot;">​</a></h2><p>6.1. Обработка персональных данных в целях направления рассылок осуществляется в соответствии с <a href="/privacy-policy">Политикой конфиденциальности</a>.</p><p>6.2. Оператор не передаёт контактные данные Субъекта третьим лицам для целей рекламных рассылок.</p><h2 id="_7-контактные-данные-оператора" tabindex="-1">7. Контактные данные Оператора <a class="header-anchor" href="#_7-контактные-данные-оператора" aria-label="Permalink to &quot;7. Контактные данные Оператора&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p>',31)])])}const u=r(s,[["render",n]]);export{g as __pageData,u as default};
